            Q.data_ptr(),
            K.data_ptr(),
            V.data_ptr(),
            out.data_ptr(),
            int(B),
            int(H),
            int(S),
            int(D)
        ]

        ptx_launch(self.module, "sdpa_naive", grid, block, args)
