    add.u32 %r_tmp2, %r_tmp2, %r_t;
    mul.lo.u32 %r_v_idx, %r_tmp2, %rD;
    add.u32 %r_v_idx, %r_v_idx, %r_dim;
    mul.wide.u32 %rd_v_off, %r_v_idx, 2;
    add.s64 %rd_v, %rdV, %rd_v_off;
    ld.global.f16 %h2, [%rd_v];
    cvt.f32.f16 %f_v, %h2;

    // accumulate weighted V
    fma.rn.f32 %f_out, %f_v, %f_wt, %f_out;

    add.u32 %r_t, %r_t, 1;
    bra $L_OUT_LOOP;

$L_OUT_END:
    // Store result (fp16)
    cvt.rn.f16.f32 %h3, %f_out;
    st.global.f16 [%rd_out], %h3;

$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 contiguous tensors
        Q = Q.to(torch.float16).contiguous()
        K = K.to(torch.float16).contiguous()
        V = V.to(torch.float16).contiguous()
        out = torch.empty_like(Q, dtype=torch.float16)

        B, H, S, D = Q.shape

        # Launch configuration: one thread per output element (B, H, S, D)
        grid = (S, H, B)          # (seq_len, heads, batch)
        block = (D, 1, 1)         # one thread per embedding dimension

        args = [
            Q.data_ptr(),
            K.data_ptr(),
            V.data_ptr(),
            out.data_ptr(),
            int(B),
            int(H),
            int(S),
            int(D)
        ]

        ptx_launch(self.module, "sdpa_naive", grid, block, args)
        return out
